UPDATE som_sales_store
SET platform = #{platform},
    store_code = #{storeCode},
    store_name = #{storeName},
    status = #{status},
    updated_at = #{updatedAt}
WHERE tenant_id = #{tenantId}
  AND store_id = #{storeId}

